// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed param: an address caller that will invoke endConfiguration()
    function testFuzz_property(address caller) public {
        // keep caller non-zero to be a meaningful actor, but otherwise unconstrained
        vm.assume(caller != address(0));

        // simulate the call from the fuzzed caller
        vm.prank(caller);
        bool ok;
        // call endConfiguration and record whether it reverts or not (it shouldn't)
        try c.endConfiguration() {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference property: after endConfiguration() returns (or even if called by any caller),
        // the correct contract sets configured == true. We assert that configured() is true when the call succeeded.
        // This will hold for the reference and fail for the mutant for some inputs (the mutant sets configured=false).
        if (ok) {
            assertTrue(c.configured(), "endConfiguration must set configured == true");
        } else {
            // If the call reverted, still assert that configured is true (covers impls that may revert but previously set state)
            assertTrue(c.configured(), "endConfiguration must set configured == true even if call reverted");
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz parameter: a boolean initialConfigured to simulate prior state by calling endConfiguration that many times.
    // We cannot directly set storage, so we simulate by calling endConfiguration N times where N = initialConfigured ? 1 : 0
    // but fuzzer provides a uint256 to decide number of prior calls; keep wide domain.
    function testFuzz_property(uint256 priorCalls) public {
        // General rule: In the correct contract, a call to endConfiguration() should set configured == true regardless
        // of prior state. The mutant toggles configured so for some priorCalls the value after calling will be false.

        // Keep domain reasonable but wide: bound priorCalls to a small number to avoid gas issues.
        uint256 n = bound(priorCalls, 0, 10);

        // Simulate arbitrary prior history by calling endConfiguration n times.
        // Using try/catch to capture any unexpected reverts (should not revert).
        for (uint256 i = 0; i < n; i++) {
            // call endConfiguration; it is a public function
            try c.endConfiguration() {
                // ok
            } catch {
                // should not revert in reference; still continue
            }
        }

        // Now perform the decisive call
        bool ok;
        try c.endConfiguration() {
            ok = true;
        } catch {
            ok = false;
        }

        // Assertion: after making the decisive call, configured() must be true on the reference.
        // This is a single assertTrue observing c via its public getter. The mutant (which toggles) will fail for some prior n.
        assertTrue(c.configured() == true);
    }
}

