pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzz the caller address to ensure property holds regardless of who calls
    function testFuzz_property(address caller) public {
        // keep caller non-zero to be a sensible caller
        vm.assume(caller != address(0));

        // call endConfiguration as the fuzzed caller
        vm.prank(caller);
        bool ok;
        try c.endConfiguration() {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: after endConfiguration returns (whether it reverted or not),
        // for the correct contract configured() should be true. We assert that.
        // This will pass for the reference and fail for the mutant (which leaves it false).
        assertTrue(c.configured() == true);
    }
}

contract InvMutTest {
    C public c;

    constructor(C _c) {
        c = _c;
    }

    // single public function with all test logic
    // params:
    // initialDaoWasZero: choose whether we want DAO initially zero (false means DAO already set)
    // callerIsDao: whether this contract will be the DAO when calling setDAO
    // newDao: the address we attempt to set as DAO
    // We cannot change msg.sender externally; instead we use the observable behavior of c.setDAO when called from this contract.
    function run(bool initialDaoWasZero, bool callerIsDao, address newDao) public {
        // Preconditions: if initialDaoWasZero is true, ensure c.DAO() == address(0)
        // If false, we require c.DAO() != address(0)
        if (initialDaoWasZero) {
            require(c.DAO() == address(0), "pre: DAO must be zero");
        } else {
            require(c.DAO() != address(0), "pre: DAO must be non-zero");
        }

        // If we want this contract to be the DAO when calling setDAO, and it's not currently DAO,
        // then we must rely on c.setDAO being callable to set DAO to this address first.
        // Do that only when allowed by the original contract behavior: when DAO==address(0) or msg.sender==DAO or not configured.
        // We drive the minimal sequence: attempt to set DAO to address(this) if needed.

        // If callerIsDao is true and this contract is not already DAO, try to make it DAO by calling setDAO
        if (callerIsDao && c.DAO() != address(this)) {
            // This call will succeed in original P iff (DAO==0) or msg.sender==DAO or not configured.
            // We make the call; if it reverts the test will revert (which is acceptable under our construction).
            c.setDAO(address(this));
            // after this, c.DAO() should be address(this) in P
        }

        // Now perform the decisive call: attempt to change DAO to newDao from this contract
        c.setDAO(newDao);

        // Finally assert the distinguishing property:
        // In the original P: if before the decisive call DAO != address(0) and msg.sender != previous DAO, setDAO should revert;
        // equivalently, after our call, if initial state had DAO != 0 and we were not DAO and we did not make ourselves DAO earlier,
        // then DAO must remain unchanged (not equal to newDao). In M the restriction prevents non-DAO from setting DAO, so if we had earlier managed to become DAO only because DAO was zero, behavior differs.

        // We choose a simple, checkable invariant: if before the decisive c.DAO() was non-zero and != address(this) (we were not DAO), then after calling setDAO(newDao) the DAO cannot equal newDao.
        // Read the DAO after the call and compare.
        address daoAfter = c.DAO();
        // Require the precondition used in the assertion to make it general and distinguishing
        // (this ensures the rule targets the change in who is allowed to call setDAO).
        require(!(/*negation of assertion precondition*/ false), "");

        // EXACTLY ONE assert as required: express that if prior to the decisive call there was a non-zero DAO different from this contract,
        // then the DAO cannot become equal to newDao.
        // We must obtain the prior DAO value. We can get it by logic: it was either address(this) (if we made ourselves DAO above) or whatever c.DAO() returned at start.
        // For verifier simplicity, capture startDAO at function entry.
    }

    // To comply with the spec that all logic be in a single public function and end with exactly one assert,
    // we provide a wrapper that actually implements the sequence and assertion with a captured startDAO.
    function testInvoke(address newDao) public {
        address startDAO = c.DAO();

        // require startDAO is non-zero and not this contract so the distinguishing condition is relevant
        require(startDAO != address(0) && startDAO != address(this), "pre: startDAO must be non-zero and not this");

        // Attempt to call setDAO from this contract; in P this should revert (so the call will revert and test stops) OR leave DAO unchanged.
        // We perform the call and then check the DAO value.
        // State-changing call must be top-level statement.
        // This call distinguishes P and M because M allows only msg.sender==DAO to call setDAO when DAO!=0, so here it should revert in both;
        // However the mutant's tightened require will cause different reachable states when earlier a non-DAO could have changed DAO — to keep test simple, we assert the general rule:
        c.setDAO(newDao);

        address daoAfter = c.DAO();

        // EXACTLY ONE assert: if the caller wasn't the DAO at start (startDAO != address(this)) and startDAO != address(0), DAO must not have changed to newDao
        assert(!(startDAO != address(0) && startDAO != address(this) && daoAfter == newDao));
    }

    // fallback/receive not used but allowed
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address daoBefore, uint8 maxGovernanceChangePerEpoch, uint256 epochSize, uint8 changeTolerance, address asset, uint256 amount, uint256 unlockTime, bool assetBurnable) public payable {
        // precondition: the contract must be configured so governance enforcement logic in setDAO path is relevant
        require(c.configured() == true, "need configured true");
        // record DAO before the sequence
        address dao0 = c.DAO();
        // ensure caller is NOT the current DAO to exercise the differing permission check
        require(msg.sender != dao0, "caller must not be DAO");

        // Calls that establish the state and then observe whether DAO changed
        c.configureSecurityParameters(maxGovernanceChangePerEpoch, epochSize, changeTolerance);
        c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable);

        // The general rule: if configured is true and the caller is not the DAO, these ops do not change DAO
        assert(c.DAO() == dao0);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint8 maxGovernanceChangePerEpoch, uint256 epochSize, uint8 changeTolerance, address asset, uint256 amount, uint256 unlockTime, bool assetBurnable) public payable {
        // precondition: DAO already set (nonzero) and caller of these configuration functions is not DAO
        address beforeDAO = c.DAO();
        require(beforeDAO != address(0), "pre: DAO zero");
        require(msg.sender != beforeDAO, "pre: caller is DAO");

        c.configureSecurityParameters(maxGovernanceChangePerEpoch, epochSize, changeTolerance);
        c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable);

        // After these calls, DAO must remain unchanged for the original contract but mutated version can change it.
        assert(c.DAO() == beforeDAO);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint8 maxGovernanceChangePerEpoch, uint256 epochSize, uint8 changeTolerance, address asset, uint256 amount, uint256 unlockTime, bool assetBurnable) public payable {
        // no special precondition; we observe DAO before/after the two configuration calls
        address daoBefore = c.DAO();
        c.configureSecurityParameters(maxGovernanceChangePerEpoch, epochSize, changeTolerance);
        c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable);
        address daoAfter = c.DAO();
        assert(daoAfter == daoBefore);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint8 maxGovernanceChangePerEpoch, uint256 epochSize, uint8 changeTolerance, address asset, uint256 amount, uint256 unlockTime, bool assetBurnable) public payable {
        // Precondition: target contract is already configured (so Governable.configured()==true in original)
        require(c.configured() == true);

        // record DAO before the calls
        address daoBefore = c.DAO();

        // make the two calls that in the mutant can change DAO due to restricted setDAO
        c.configureSecurityParameters(maxGovernanceChangePerEpoch, epochSize, changeTolerance);
        c.configureFlashGovernance(asset, amount, unlockTime, assetBurnable);

        // In the original contract these calls do not change DAO when caller is not DAO and contract is configured.
        // Assert DAO unchanged.
        assert(c.DAO() == daoBefore);
    }
