}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // Fuzzed parameters: caller address and emergency flag, and an arbitrary asset/amount to set in config
    function testFuzz_property(address caller, bool emergency, address asset, uint256 amount) public {
        // keep caller non-zero to be meaningful
        vm.assume(caller != address(0));

        // Configure flashGovernanceConfig so assertGovernanceApproved will attempt an ERC20 transferFrom
        // We'll deploy a minimal ERC20-like token that returns true on transferFrom so the call succeeds.
        SimpleToken token = new SimpleToken();
        // set token as the asset in c via a successful proposal path (we are DAO initially so use onlySuccessfulProposal allowed)
        // c was constructed with DAO = address(this) so msg.sender == DAO here; call configureFlashGovernance
        c.configureFlashGovernance(address(token), amount == 0 ? 1 : amount, 1, false);

        // Record DAO before the call
        address daoBefore = c.DAO();

        // We need to have the token allow transferFrom from caller to c. Since we control token, set allowance accordingly.
        // Mint balance to caller and approve c to pull it
        token.mint(caller, amount == 0 ? 1 : amount);
        vm.prank(caller);
        token.approve(address(c), amount == 0 ? 1 : amount);

        // Now call assertGovernanceApproved from the fuzzed caller. We must route the call as that caller.
        // If caller is a contract with no code the transferFrom will still succeed because our token handles it.
        vm.prank(caller);
        bool ok;
        try c.assertGovernanceApproved(caller, address(this), emergency) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call, DAO must remain unchanged for the reference contract for ALL inputs.
        // The mutant can change DAO in some scenarios; so we assert equality.
        assertTrue(c.DAO() == daoBefore);
    }
}

// Minimal token that behaves as an ERC20 and always returns true for transferFrom
contract SimpleToken {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function mint(address to, uint256 amt) public {
        balanceOf[to] += amt;
    }

    function approve(address spender, uint256 amt) public returns (bool) {
        allowance[msg.sender][spender] = amt;
        return true;
    }

    function transferFrom(address from, address to, uint256 amt) public returns (bool) {
        uint256 allowed = allowance[from][msg.sender];
        require(allowed >= amt, "not allowed");
        require(balanceOf[from] >= amt, "insufficient");
        allowance[from][msg.sender] = allowed - amt;
        balanceOf[from] -= amt;
        balanceOf[to] += amt;
        return true;
    }
}

