pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: an arbitrary caller and an arbitrary boolean emergency flag
    function testFuzz_property(address caller, bool emergency) public {
        // Keep wide domain but avoid zero-address for caller because we need to impersonate it
        vm.assume(caller != address(0));

        // Record DAO before the call
        address daoBefore = c.DAO();

        // We need to cause assertGovernanceApproved to execute its logic. That logic requires
        // IERC20(flashGovernanceConfig.asset).transferFrom(...) to return true and pendingFlashDecision[...] unlockTime < block.timestamp.
        // The easiest way is to set flashGovernanceConfig.asset to an ERC20-like contract that returns true on transferFrom.
        // But we cannot call configureFlashGovernance (onlySuccessfulProposal) in setup; however setDAO in constructor set DAO to address(this).
        // Since our test only needs to call assertGovernanceApproved which is public and guarded by flashEnabled (msg.sender == DAO || governed[msg.sender]).
        // To reach the internal branch that ends up calling setDAO indirectly we don't need all side effects; we only need to call assertGovernanceApproved and check DAO didn't change.
        // Call as arbitrary caller: use vm.prank to impersonate caller.

        vm.prank(caller);
        // call and ignore revert or success; assertGovernanceApproved is public and may revert; we only care whether DAO changes after the call.
        // Use try/catch to ensure call doesn't bubble and break the test harness.
        bool ok;
        try c.assertGovernanceApproved(caller, address(c), emergency) {
            ok = true;
        } catch {
            ok = false;
        }

        // The invariant: c.DAO() must remain equal to its previous value for the reference implementation for all inputs.
        // The buggy mutant may allow DAO to change in some cases; this single assertion distinguishes them.
        assertTrue(c.DAO() == daoBefore);
    }
}

