pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // fuzzing an actor address that will act as the caller of assertGovernanceApproved
    // we also fuzz a bool emergency; keep domain wide
    function testFuzz_property(address caller, bool emergency) public {
        vm.assume(caller != address(0)); // keep it meaningful but wide

        // capture DAO before the call
        address daoBefore = c.DAO();

        // We need to invoke assertGovernanceApproved on c as 'caller'.
        // The function is public and has the flashEnabled modifier which allows DAO or governed addresses.
        // To ensure the call is permitted by flashEnabled, make 'caller' be treated as DAO via setDAO if possible.
        // The reference contract's setDAO allows non-DAO until configured; constructor set DAO to address(this),
        // but we will attempt to change DAO via a call from this test actor to create a difference in mutant.

        // First, ensure c is unconfigured so setDAO can be called by non-DAO in reference.
        // c was constructed with DAO = address(this) and configured is default false; that's sufficient.

        // Now prank as 'caller' to call setDAO on c trying to set DAO to caller.
        vm.prank(caller);
        // In the reference contract, setDAO will succeed when DAO == address(0) || msg.sender == DAO || !configured
        // Since configured == false, setDAO from any caller should succeed in reference; in mutant it requires msg.sender==DAO.
        // We call setDAO to attempt to set DAO to caller. If the mutant reverts here, the later assertGovernanceApproved will still be executed
        // but DAO change didn't happen; this is part of distinguishing behavior after assertGovernanceApproved later.
        // We don't catch revert here; if it reverts the test will stop — so protect with try/catch.
        try c.setDAO(caller) {
            // ok
        } catch {
            // ignore revert from mutant; proceed — DAO stays unchanged in that case
        }

        // Now call assertGovernanceApproved as 'caller' on c.
        // We need to provide a target address; use address(0xdead) (fuzzing that is unnecessary)
        address target = address(0xDEAD);

        // Perform the call as 'caller' and ignore revert — we only care about DAO stored value after the call.
        vm.prank(caller);
        try c.assertGovernanceApproved(caller, target, emergency) {
            // call succeeded
        } catch {
            // call reverted; still proceed to check DAO
        }

        // Exactly one assertion: the correct contract preserves DAO after the above operations for all inputs.
        // The reference contract allows setDAO to be called by non-DAO while not configured, but asserts that subsequent
        // governance flows should not leave DAO changed by assertGovernanceApproved. We check that DAO equals daoBefore.
        assertTrue(c.DAO() == daoBefore);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // Fuzz the candidate caller address and the emergency flag. The fuzzer will search for inputs that
    // make the mutant diverge: in the reference, DAO never changes as a result of assertGovernanceApproved;
    // the mutant can cause DAO to change for some caller. We must ensure the caller is not the contract itself
    // (address(this) is the initial DAO passed to constructor) so we allow other addresses.
    function testFuzz_property(address caller, bool emergency) public {
        // keep caller != address(0) to avoid degenerate EOA zero address
        vm.assume(caller != address(0));
        // ensure we fuzz callers different from the initial DAO to enable the mutant-specific path
        vm.assume(caller != address(this));

        // Record DAO before the call
        address before = c.DAO();

        // We will call assertGovernanceApproved from the fuzzed caller. The function is public and will
        // execute code that may do external calls (IERC20.transferFrom). Those will call into the
        // caller address we supply; to keep behavior admissible but not rely on empty EOA semantics,
        // we deploy a helper that implements transferFrom and returns true so the call succeeds.
        // However, the reference property we assert is independent of token transfer semantics; we
        // only need a valid external callee. We deploy an instance of TokenLike and have the caller be
        // that contract so that the external call goes to contract code, not an empty EOA.

        // Deploy a simple token-like helper that returns true for transferFrom and is used as the caller.
        TokenLike token = new TokenLike();

        // Now we need to ensure the contract's flashGovernanceConfig.asset equals the token address and
        // amount is zero so transferFrom will be called but not require funds. Configure via the public
        // configureFlashGovernance which requires onlySuccessfulProposal; since setUp constructed c with
        // this test contract as DAO, and setDAO allowed DAO initially, we must make this contract a
        // successful proposal caller. The simplest is to call configureFlashGovernance from address(this)
        // because setUp passed address(this) as the DAO and the contract expects onlySuccessfulProposal
        // which checks LimboDAOLike(DAO).successfulProposal(msg.sender). However, we cannot call that.
        // To avoid needing proposal machinery, we instead directly set the flashGovernanceConfig by calling
        // the public function configureFlashGovernance which is onlySuccessfulProposal — but we (address(this))
        // were provided as DAO at construction and the require in Governable.onlySuccessfulProposal will call
        // assertSuccessfulProposal(msg.sender) which in turn requires(!configured || LimboDAOLike(DAO).successfulProposal(sender)).
        // At construction, configured starts false, so onlySuccessfulProposal allows calls. So we can call it now.

        // Configure the contract so asset is the token helper and amount is zero (safe)
        c.configureFlashGovernance(address(token), 0, 1, false);

        // Now call assertGovernanceApproved as if from the fuzzed caller. We need to arrange that the external
        // transferFrom on the token is invoked with 'caller' as the sender. The contract calls
        // IERC20(flashGovernanceConfig.asset).transferFrom(sender, address(this), flashGovernanceConfig.amount)
        // where 'sender' is the first argument to assertGovernanceApproved. Thus we pass the 'caller'
        // value as that argument and ensure the asset points to our token contract which will receive the
        // transferFrom call from the C contract (C -> token.transferFrom(caller,...)). Our TokenLike
        // implementation ignores who called transferFrom and returns true.

        // Prepare parameters: target can be any address; pass address(0) to keep it simple
        address target = address(0);

        // Call assertGovernanceApproved from this test (external invocation), but with the 'sender' param equal to fuzzed caller.
        // The function is public, so we just call it. It will call token.transferFrom(caller, ...)
        bool ok;
        try c.assertGovernanceApproved(caller, target, emergency) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call, the reference contract guarantees DAO remains unchanged for all inputs.
        // The mutant can change DAO for some inputs; assert that DAO is still the same as before.
        assertTrue(c.DAO() == before);
    }
}

// Minimal token-like helper used as the external asset; transferFrom always returns true.
contract TokenLike {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}

