        if (doReenter && attacker != address(0)) {
            // attacker is a contract that will call setDAO on C
            (bool s, ) = attacker.call(abi.encodeWithSignature("attack(address)", address(this)));
            // ignore success
            s; // no-op to silence warnings
        }
        return true;
    }
}

contract Attacker {
    C public victim;
    address public newDAO;

    constructor(C _victim) {
        victim = _victim;
    }

    // Called by ReentrantToken to perform the reentrant setDAO call on victim
    function attack(address token) external {
        // set DAO to a different address to observe change
        victim.setDAO(newDAO);
    }

    // helper to configure desired new DAO
    function setNewDAO(address d) external {
        newDAO = d;
    }
}

contract InvMutTest is Test {
    C c;
    ReentrantToken tok;
    Attacker attacker;

    function setUp() public {
        c = new C(address(this));
        // deploy token pointing at c
        tok = new ReentrantToken(address(c));
        attacker = new Attacker(c);
    }

    // fuzz parameters:
    // - addrToSet: address attacker will set as new DAO during reentry (must not be zero)
    // - doReenterFlag: whether token will reenter during transferFrom
    function testFuzz_property(address addrToSet, bool doReenterFlag) public {
        // keep addrToSet wide but non-zero to be a meaningful DAO
        vm.assume(addrToSet != address(0));

        // arrange: configure victim's DAO to some initial value (this contract)
        c.setDAO(address(this));
        // read initial governer
        address govBefore = address(c.governer());

        // configure attacker to set DAO to addrToSet
        attacker.setNewDAO(addrToSet);

        // configure the token to reenter (or not) via attacker
        tok.configure(address(attacker), doReenterFlag);

        // wire c's flashGovernanceConfig.asset to be our token so transferFrom is used
        // we need to call configureFlashGovernance which is onlySuccessfulProposal; bypass by making this contract the proposer
        // set up minimal successfulProposal behavior by using setDAO already set and calling setGoverned not required here
        // Configure via low-level call to c.configureFlashGovernance assuming onlySuccessfulProposal check passes because msg.sender == DAO
        vm.prank(address(this));
        c.configureFlashGovernance(address(tok), 1, 1 minutes, false);

        // Now perform the call that will invoke token.transferFrom inside assertGovernanceApproved
        bool ok;
        // call assertGovernanceApproved with sender = address(this) (will cause token.transferFrom called)
        try c.assertGovernanceApproved(address(this), address(0x1234), false) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call, on the correct reference implementation governer should remain unchanged.
        // This is a single assertion reading c's public getter.
        assertTrue(address(c.governer()) == govBefore);
    }
}

