pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

// Minimal ERC20-like token that on transferFrom will reenter target contract
contract ReentrantToken {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    address public victim;
    address public attacker;

    constructor(address _victim, address _attacker) {
        victim = _victim;
        attacker = _attacker;
    }

    function setBalance(address who, uint256 amount) public {
        balanceOf[who] = amount;
    }
    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }
    // transferFrom will call back into victim.assertGovernanceApproved to attempt to change DAO
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(balanceOf[from] >= amount, "bal");
        if (allowance[from][msg.sender] < amount) revert("allow");
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        // reenter: call attacker which will try to call setDAO on victim
        // attacker is a contract we deploy that will call setDAO on victim
        // We use low-level call so it can be any function on attacker
        (bool ok, ) = attacker.call(abi.encodeWithSignature("attack()"));
        // ignore attack result; original code's transferFrom returns success only if true
        return true;
    }
}

// Attacker contract that when invoked will try to change victim.DAO by calling setDAO
contract DAOChanger {
    address public victim;
    address public newDAO;
    constructor(address _victim, address _newDAO) {
        victim = _victim;
        newDAO = _newDAO;
    }
    // called from token during transferFrom reentrancy
    function attack() external {
        // try to call setDAO on victim; will succeed only if caller meets setDAO require
        // use low-level call to ignore revert
        (bool success, ) = victim.call(abi.encodeWithSignature("setDAO(address)", newDAO));
        // ignore success
        success;
    }
}

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // fuzz parameters: attackerInitialBalance and amount to transfer
    function testFuzz_property(uint256 attackerInitialBalance, uint256 transferAmount) public {
        // keep values wide but non-zero where useful
        attackerInitialBalance = bound(attackerInitialBalance, 1, 1e24);
        transferAmount = bound(transferAmount, 1, attackerInitialBalance);

        // deploy attacker that will attempt to change DAO to some new address
        address newDao = address(0xBEEF);
        DAOChanger changer = new DAOChanger(address(c), newDao);

        // deploy reentrant token with victim c and attacker changer
        ReentrantToken token = new ReentrantToken(address(c), address(changer));

        // fund attacker (from) and set allowance for msg.sender (which will be the flashGovernance caller)
        token.setBalance(address(this), attackerInitialBalance);
        token.approve(address(this), attackerInitialBalance);

        // configure c to use our token as flashGovernance asset and set amount
        // need to be a successful proposal caller — set DAO to this contract initially so onlySuccessfulProposal modifier allows
        // c was constructed with DAO = address(this) in setUp, so we're allowed to call configureFlashGovernance
        c.configureFlashGovernance(address(token), transferAmount, 1, false);

        // record DAO before call
        address before = c.DAO();

        // perform assertGovernanceApproved: it will call IERC20(token).transferFrom(sender,..)
        // we call it as this contract (msg.sender == address(this)) and token.transferFrom will reenter and attempt to setDAO
        bool ok;
        try c.assertGovernanceApproved(address(this), address(0xCAFE), false) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call, on the correct contract DAO must remain unchanged for all inputs
        // The mutant that deletes governer early can allow the reentrant attacker to change DAO during the transferFrom
        assertTrue(c.DAO() == before);
    }
}
